head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > noResultMessageStylePriority]<br/>noResultMessageCenter=true 일때 noResultMessageClass, noResultMessageStyle 속성의 적용 여부를 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 엔진의 자동 설정값을 적용하고 noResultMessageClass, noResultMessageStyle 속성은 무시됩니다.",
        "true 설정 시 엔진의 자동 설정값 대신 noResultMessageClass, noResultMessageStyle 속성을 적용합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    // 조건 설정   
    let properties = {
        noResultMessageStylePriority: con_noResultMessageStylePriority.getText(),
        noResultMessageClass: "noResultMessage_class1",
        noResultMessageStyle: "text-decoration-color: red; top:40%;",
        noResultMessageVisible: true,
        useNoResultMessageURL: false,
        noResultMessageCenter: true,
        dataList: "data:dlt_bind",      
    };

    let cList = $c.gcm.createCList(properties);      
    // let eList = $c.gcm.createEList([]) 

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성   
    let grp_comp = document.querySelector('.tc_group_basic');  
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();    

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:350px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';    
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';    
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';    

    // target 생성
    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    scwin.btn_setJSON_onclick();
}



scwin.btn_setJSON_onclick = function (e) {
	dlt_bind.setJSON([]);

    scwin.btn_noResultMessage_onclick();
};



scwin.btn_noResultMessage_onclick = function (e) {
    // let targetElement = document.querySelector('div[id*="target1_noresult"]');
    let targetElement = document.querySelector('div[id$="target1_noresult"]');

    if (targetElement) {
        let textDecorationValue = targetElement.style.textDecorationColor;
        let topValue = targetElement.style.top;
        let className = targetElement.className;

        wf_body_bottom.getObj("scwin").setReturnValue("style.textDecorationColor : " + textDecorationValue);	
        wf_body_bottom.getObj("scwin").setReturnValue("style.top : " + topValue);	
        wf_body_bottom.getObj("scwin").setReturnValue("className : " + className);	
    }
}
